import"./chunk-2NFLSA4Y.js";var s={inertia:{theory:{concept:"[[Newton's first law (the law of inertia): a body stays at rest or keeps moving in a straight line at constant speed as long as no force acts on it or the forces on it balance.]] The property of a body to keep its velocity is called inertia; the larger the mass, the larger the inertia. For example, if you jump straight up in a bus moving steadily at 54 km/h, you land where you took off: in the air you keep moving forward at the bus's speed, because nothing stops you. The law holds in inertial frames of reference, such as the ground or a bus moving steadily in a straight line."},section:{inertia:{title:"Inertia",text:"Every object keeps doing what it is doing: if it is at rest it stays at rest; if it moves, it keeps moving at the same speed in the same direction. To change this, a force is needed."},bus:{title:"Back to the bus",text:"[[If the bus suddenly brakes while you are in the air, you land further forward \u2014 you kept the old speed but the bus slowed down.]] If it speeds up, you land further back. In the bus it feels as if something pushed you, but no force did: the bus changed its speed, not you."},everyday:{title:"In everyday life",text:"When a bus brakes, standing passengers lean forward. Seat belts stop us from flying forward in a crash. A quick pull can take a tablecloth from under the dishes, because the dishes tend to stay where they are."},frames:{title:"Frames of reference",text:"Motion always depends on who is looking. From inside the bus your jump goes straight up and down; from the street the same jump is an arc moving forward with the bus. Both are correct \u2014 they are seen from different frames of reference."},galileo:{title:"Galileo's ship",text:"Galileo noticed that in the cabin of a ship sailing smoothly, everything happens exactly as on land: drops fall straight down and a ball thrown up comes back to your hand. From inside you cannot tell whether you are moving at constant speed."},earth:{title:"We are always moving",text:"The Earth carries us around the Sun at about 30 km/s, and its rotation moves us at up to 465 m/s at the equator. We do not feel it, because we, the air and everything around us move together \u2014 just like you and the bus."}},formula:{firstLaw:"Newton's first law: without force, the speed does not change",relative:"Speed seen from a frame moving with speed V",airTime:"Time in the air for a jump with take-off speed v\u2080",offset:"How far you land from the take-off spot if the bus changes speed with acceleration a"},variable:{v:"Speed seen from the street",V:"Speed of the bus",vRel:"Speed seen from inside the bus"},assumption:{air:"The air inside the bus moves with the bus; there is no air resistance.",point:"The passenger is treated as a single point; the jump goes straight up relative to the bus.",constant:"The bus brakes or speeds up evenly, only while the passenger is in the air.",friction:"After landing the passenger's shoes grip the floor and they move with the bus again."},param:{frame:"Point of view",busSpeed:"Bus speed",scenario:"During the jump the bus\u2026",jumpSpeed:"Jump speed (upwards)",busAcceleration:"Braking / acceleration of the bus"},hint:{frame:"Switch the view while the passenger is in the air.",scenario:"What happens if the bus changes its speed while you are in the air?",jumpSpeed:"A stronger jump means more time in the air."},frame:{bus:"From inside the bus",ground:"From the street"},scenario:{constant:"keeps the same speed",braking:"brakes",accelerating:"speeds up"},measure:{busSpeed:"Bus speed",height:"Jump height",groundSpeed:"Passenger's forward speed (from the street)",relativeSpeed:"Passenger's forward speed (inside the bus)",airTime:"Time in the air",busDistance:"Distance the bus travelled during the jump",landingOffset:"Landed from the take-off spot (cm, + = forward)"},graph:{speeds:"Forward speed over time (from the street)",bus:"Bus",passenger:"Passenger"},view:{busFrame:"View from inside the bus",groundFrame:"View from the street",busSpeed:"bus: {speed}",takeoff:"jumped here",sameSpot:"landed on the same spot",offset:"landed {offset} cm away",getReady:"The passenger will jump in a moment\u2026",braking:"the bus brakes!",accelerating:"the bus speeds up!"},challenge:{sameSpot:{title:"Same spot, even at speed",description:"Jump in a bus going at least 20 m/s (72 km/h) at constant speed and land on the same spot.",hint:"Set the bus speed and press Play. Watch the mark on the floor."},street:{title:"Seen from the street",description:"Watch a whole jump from the street.",hint:"Choose \u201CFrom the street\u201D as the point of view. What shape is the path now?"},braking:{title:"Sudden braking",description:"Make the bus brake during the jump so that you land more than 10 cm further forward.",hint:"Choose \u201Cbrakes\u201D. Why do you land in front of the mark?"},accelerating:{title:"Left behind",description:"Make the bus speed up during the jump so that you land more than 10 cm further back.",hint:"Choose \u201Cspeeds up\u201D."},metre:{title:"A metre forward",description:"Land at least 1 m in front of the take-off spot in a braking bus.",hint:"\u0394x = \xBD\xB7a\xB7T\xB2. Increase the braking and the jump speed (longer time in the air)."}}}},a={sim:s};export{a as default,s as sim};
